use super::*;

/// The tier `id` is already recorded on in `lane`, or [`TIER_IMPL`] if it is not recorded at all.
///
/// Every write that CONTINUES a record — a tombstone, a revert — has to carry the tier forward rather
/// than assume one. Both of those used to assume `impl` (a revert through [`put`], a tombstone through
/// the column's `DEFAULT 'impl'`), which silently reclassified an EDGE as an implementation: it
/// vanished from `document()["edges"]` and reappeared among the implementations, where a build would
/// try to compile it.
pub fn tier_in(conn: &Connection, lane: &str, id: &str) -> Result<String, String> {
    conn.query_row(
        "SELECT tier FROM record_revs WHERE id = ?1 AND lane = ?2 ORDER BY rev DESC LIMIT 1",
        params![id, lane],
        |r| r.get::<_, String>(0),
    )
    .or_else(|e| match e {
        rusqlite::Error::QueryReturnedNoRows => Ok(TIER_IMPL.to_string()),
        other => Err(format!("cannot read the tier of '{id}' in lane '{lane}': {other}")),
    })
}
